"""나니 설명(NOTE) 문구 — build_nani.py가 globals()를 넘겨 부름"""

def make_note(V):
    M, E, ST, CN = V["M"], V["E"], V["ST"], V["CN"]
    judg, SRC, SRC_A = V["judg"], V["ELO_SRC"], V["SRC_A"]
    def d_(s): y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"
    def c3(v): return f"{v[0]}·{v[1]}·{v[2]}"
    first, last = M[0], M[-1]
    pkx = [j for j in judg if j[0] == "도움 제외" and j[5] == "PK 유도"]
    shx = [j for j in judg if j[0] == "도움 제외" and j[5].startswith("슈팅")]
    ogx = [j for j in judg if j[0] == "도움 제외" and j[5] == "상대 자책골 유도"]
    unc = [j for j in judg if j[0] == "도움 제외(단일 출처 미확인)"]
    man = sorted({(o, v[1], v[2]) for (o, d), v in V["ELO_LOG"].items() if v[0] == "man"})
    cnf = V["ADD_CONFIRMED"]
    lst = lambda js: ", ".join(f"{d_(j[1])} {j[2]}전 {j[3]}분 {j[4]}" for j in js)
    L = [
        f"나니(스포르팅 CP·맨체스터 유나이티드·페네르바흐체·발렌시아·라치오·올랜도 시티·베네치아·멜버른 빅토리·아다나 데미르스포르·에스트렐라 다 아마도라·악퇴베)의 클럽 공식 경기 {V['NG']}경기({d_(first[0])} {first[1]}전 ~ {d_(last[0])} {last[1]}전)에서 나온 {V['NGo']}골 {V['NA']}도움(PK 골 {V['NPK']}개), 친선경기·포르투갈 대표팀·MLS 올스타전 제외",
        "클럽별 경기·골·도움: " + ", ".join(f"{CN[k]} {c3(v)}" for k, v in ST.items()) + f"(스포르팅은 2005~07·2014-15 임대·2018-19 세 시기 합계). 출전 분 합계 {V['MIN_TOT']:,}분",
        f"출처: 경기 목록·출전 분은 Transfermarkt 선수 경기 성적, 골 시각·골 순서·PK·도움은 Transfermarkt 경기 리포트(골·도움이 있는 경기와 리그 밖 경기 전부). 경기 수·골은 영어 위키백과 클럽·시즌별 기록·FotMob 경력 합계와 대조(골은 영어 위키백과 시즌별 합계와 같음). FotMob 경기 기록(2010-11부터)과 골 {V['FM_N']}경기를 대조해 골 수·PK가 같음(2015.2.22 질 비센트전 골 시각 Transfermarkt 69분·FotMob 67분은 Transfermarkt 기준)",
        "경기 수 차이: 영어 위키백과 시즌별 표가 Transfermarkt보다 5경기 많음 — 스포르팅 2005-06·2006-07 타사 드 포르투갈 각 2경기(Transfermarkt는 명단 제외·벤치)와 멜버른 빅토리 2022-23 1경기(2023.4.5 멜버른 시티전: FotMob 선수 경기 목록에는 있으나 FotMob 라인업에 없고 Transfermarkt는 부상 결장). Transfermarkt 출전 경기만 셈. 올랜도 2020·2021은 대회 분류만 다르고 합계 같음. 모든 소속 팀-시즌이 1부 프로 리그",
        "출전 분: Transfermarkt 그대로. 2016.5.26 튀르키예컵 결승 갈라타사라이전은 Transfermarkt 출전 분이 0분이지만 선발 출전·교체 기록 없음·90+6분 퇴장(FotMob)이라 90분으로 넣음. 날짜는 경기 현지 날짜(올랜도 시티 저녁 경기는 미국 동부 날짜, 2008 클럽 월드컵 준결승은 요코하마 날짜)",
        f"골: Transfermarkt 132골 중 2010.1.31 아스널전 33분 1골은 뺌 — 나니의 크로스를 골키퍼 알무니아가 쳐내려다 자기 골문에 넣은 장면으로, BBC·스카이스포츠·알자지라 경기 기사와 영어 위키백과 시즌 기록이 알무니아 자책골로 적음(Transfermarkt·포르투갈어 위키백과는 나니 골). 그 경기 37분 루니 골 도움은 그대로 셈. PK 골 {V['NPK']}개(2019.5.19 신시내티전 50분은 PK가 막힌 뒤 리바운드 골이라 PK 아님)",
        f"도움: 2014년 8월 전은 Transfermarkt 리포트 단일 출처를 씀(클로제·벨한다 선례, 유형 빈칸 5개도 일반 도움으로 셈). 2014년 8월 뒤는 Transfermarkt와 FotMob(경기 이벤트 {SRC_A['TM∩FotMob 경기 이벤트']}개, 선수 경기 목록의 경기별 도움 수 {SRC_A['TM∩FotMob 선수 경기 목록']}개)이 함께 센 것과 다른 출처 2곳이 확인한 {len(cnf)}개만 넣음. Transfermarkt 도움 {V['N_TM_A']}개 − PK 유도 {len(pkx)}개({lst(pkx)}) − 슈팅 리바운드 {len(shx)}개({lst(shx)}) − 상대 자책골 유도 {len(ogx)}개({lst(ogx)}) − 확인 못 한 단독 도움 {len(unc)}개 = {V['NA']}개. 2019.8.17 미네소타전 70분 본인 PK 골에 붙은 본인 도움 표기는 도움이 아님",
        "다른 출처 2곳으로 확인해 넣은 도움: " + "; ".join(cnf.values()),
        "확인 못 해 뺀 Transfermarkt 단독 도움: " + "; ".join(j[5] for j in unc) + ". 스포르팅 2014-15 리그·악퇴베 2026 경기는 FotMob 경기 기록에 도움 자료가 없어 실제 도움보다 적을 수 있음",
        "FotMob에만 있는 도움 2개는 넣지 않음: 2011.3.19 볼턴전 88분 베르바토프 골(기사들은 나니 슛을 골키퍼가 놓친 리바운드로 적음), 2012.3.4 토트넘전 60분 애슐리 영 골(나니 크로스가 수비에 맞고 굴절돼 영에게 감, Transfermarkt 도움 없음)",
        f"상대 Elo는 같은 경기를 다룬 다른 선수 자료(루니·긱스·발렌시아·호날두·판페르시·브루누 페르난드스·이과인 등), 같은 팀·같은 시즌 다른 선수 자료 값, 직접 추정, 그 시즌 최종 순위를 기존 리그 순위값·리그 모형에 넣은 값 순으로 씀(기록 {len(E)}개: 같은 경기 {SRC['같은 경기 다른 선수 자료']}, 같은 팀·시즌 {SRC['기존 팀×시즌 값']}, 순위표+모형 {SRC['순위표+리그 모형']}, 직접 {SRC['직접 추정']})",
        "리그 수준: 포르투갈 1부는 다른 선수 자료의 같은 시즌 순위값, 없으면 팀 수가 같은 시즌(16팀 2006-07~2013-14, 18팀 그 밖)의 순위값; 포르투갈 2부는 1부 평균 − 잉글랜드 1·2부 평균 차(약 1367) 모형(추정). MLS는 전체 순위(2019·2021 서포터스 실드 표, 2020 승점률 순위)를 다른 선수 자료의 같은 시즌 순위값에 넣고 빈 순위는 앞뒤 값 사이, 끝 순위(2020 1·3·14·19·22·23위, 2021 1·4위)는 기존 MLS 순위값을 재현하는 모형(평균 약 1581, 흩어짐 약 58)으로 추정. 쉬페르리그는 같은 시즌 기존 순위값 사이(트라브존스포르 2023-24 3위 1715, 추정). 호주 A리그는 1위 1450~꼴찌 1350 직선(델 피에로·비야 자료와 같은 추정). 카자흐스탄 프리미어리그 2026은 1위 1400(다른 선수 자료 카자흐스탄 우승 팀 값)에서 순위마다 10씩 낮춘 추정(토볼 7위 1340·옐리마이 6위 1350·아스타나 3위 1380, 최종 순위는 RSSSF 2026 최종 순위표로 확인)",
        "직접 추정(모두 '추정'): " + ", ".join(f"{o} {e}({lv})" for o, e, lv in man),
        "대회 비중: 타사 드 포르투갈·타사 다 리가·FA컵·리그컵·튀르키예컵·코파 델 레이·코파 이탈리아·US 오픈컵·호주컵·카자흐스탄컵은 국내컵(16강까지 낮은 비중, 8강 이후 높은 비중; FA컵 6라운드 재경기는 8강), 튀르키예컵 2015-16 조별은 리그식, 커뮤니티 실드·UEFA 슈퍼컵은 국내컵 결승. MLS is Back 2020은 조별 3경기가 MLS 정규 리그 순위에 들어가 리그 비중, 토너먼트(16강·8강·준결승·결승)는 리그가 주최한 컵으로 보고 국내컵 단계 비중. MLS 컵 플레이오프는 단판, 리그스컵 2021 8강은 리그스컵 토너먼트, 2008 클럽 월드컵 준결승은 클럽 월드컵",
        f"두 경기 합산 기록 {V['NTIE']}개({V['NTIEG']}경기)는 합산 S로 계산함: UEFA 대회·튀르키예컵(2020-21까지)·잉글랜드 리그컵 준결승(2017-18까지)·타사 드 포르투갈 준결승·코파 델 레이·코파 이탈리아는 원정 다득점·연장. 다른 차전 스코어는 Transfermarkt 리포트",
        "시즌 구분: 올랜도 시티·악퇴베는 달력 연도, 페네르바흐체·아다나는 7월 10일 기준(2015.7.28 챔스 예선 샤흐타르전·2023.7.27 컨퍼런스 예선 클루지전이 새 시즌), 나머지는 기본 8월 1일(멜버른 빅토리 2022.8.3 호주컵은 2022-23). 클럽 구분(Transfermarkt 이적 기록): 2007.7.2 맨유, 2014.8.19 스포르팅 임대, 2015.7.7 페네르바흐체, 2016.7.5 발렌시아, 2017.8.31 라치오 임대, 2018.7.11 스포르팅, 2019.2.18 올랜도, 2022.1.14 베네치아, 2022.7.12 멜버른 빅토리, 2023.7.13 아다나, 2024.7.31 에스트렐라(2024.5~7 무소속), 2025.1~2026.1 무소속, 2026.1.25 악퇴베",
        "같은 경기 동료 자료: 루니·긱스·발렌시아·호날두·애슐리 영·판페르시(맨유·페네르바흐체)·브루누 페르난드스·하피냐(스포르팅)·임모빌레(라치오)·디에구(페네르바흐체) 자료와 서로 주고받은 골·도움의 날짜·분·골 전 스코어·대회·상대 Elo·합산 표시가 같음. 상대 팀 선수 자료(이과인·메시·수아레스·오야르사발 등)와 골 순서도 맞음",
        "몰수 경기: 나니가 뛴 경기 중 공식 판정으로 결과가 바뀐 경기는 없음",
        "수상 기록은 Transfermarkt 업적 페이지 기준: 챔스 2007-08, 클럽 월드컵 2008, 프리미어리그 2007-08·2008-09·2010-11·2012-13, 리그컵 2009·2010, 커뮤니티 실드 4회, 타사 드 포르투갈 2007·2015·2019, 타사 다 리가 2018-19(스포르팅). 챔스 준우승 2008-09·2010-11. PFA(선수협회) 프리미어리그 올해의 팀 2010-11(PFA 공식 명단). 구단 상(맨유 선수가 뽑은 올해의 선수 2010-11·스포르팅 올해의 선수 2015), 프리미어리그 도움 1위 2010-11(Transfermarkt 업적에 없음), SJPF 이달의 선수, MLS 올스타, 유로 2016(대표팀)은 뺌",
        f"마지막 갱신: 2026.11.18(마지막 반영 경기 {d_(last[0])} {last[1]}전, 카자흐스탄 프리미어리그 30라운드, 악퇴베 소속 현역 — 계약 2026.12.31까지)",
    ]
    return "\n".join(L)
